PRAGMA foreign_keys = ON;
CREATE TABLE editorial_readouts (id TEXT PRIMARY KEY, company_id TEXT REFERENCES companies(id), segment TEXT NOT NULL, readout TEXT NOT NULL, signal TEXT NOT NULL, claim_id TEXT REFERENCES claims(id), record_json TEXT NOT NULL);
CREATE TABLE dataset (version TEXT PRIMARY KEY, schema_version TEXT NOT NULL, as_of TEXT NOT NULL, canonical_json TEXT NOT NULL CHECK(json_valid(canonical_json)));
CREATE TABLE companies (id TEXT PRIMARY KEY, name TEXT NOT NULL, website TEXT NOT NULL, description TEXT NOT NULL, categories TEXT NOT NULL, entity_type TEXT NOT NULL, identity_claim_id TEXT NOT NULL REFERENCES claims(id) DEFERRABLE INITIALLY DEFERRED, profile_claim_ids TEXT NOT NULL, record_json TEXT NOT NULL);
CREATE TABLE sources (id TEXT PRIMARY KEY, company_id TEXT REFERENCES companies(id), url TEXT NOT NULL, title TEXT NOT NULL, publisher TEXT NOT NULL, source_type TEXT NOT NULL, published_on TEXT, accessed_on TEXT NOT NULL, retrieval_status TEXT NOT NULL, evidence_chain_id TEXT, archive_url TEXT, notes TEXT, record_json TEXT NOT NULL);
CREATE TABLE claims (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), subject TEXT NOT NULL, segment_scope TEXT NOT NULL, statement TEXT NOT NULL, as_of TEXT NOT NULL, observed_on TEXT NOT NULL, date_note TEXT, raw_path TEXT, raw_pointer TEXT, confidence TEXT NOT NULL CHECK(confidence IN ('A','B','C','U')), confidence_reason TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('supported','contested','superseded','unverified')), evidence_excerpt TEXT, record_json TEXT NOT NULL);
CREATE TABLE claim_sources (claim_id TEXT REFERENCES claims(id), source_id TEXT REFERENCES sources(id), relationship TEXT NOT NULL CHECK(relationship IN ('supports','historical','contradicts')), PRIMARY KEY(claim_id,source_id,relationship));
CREATE TABLE metrics (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), claim_id TEXT NOT NULL REFERENCES claims(id), segment_scope TEXT NOT NULL, kind TEXT NOT NULL, label TEXT NOT NULL, value REAL NOT NULL, upper_value REAL, qualifier TEXT NOT NULL, unit TEXT NOT NULL, currency TEXT, as_of TEXT NOT NULL, period_label TEXT, period_start TEXT, period_end TEXT, basis TEXT NOT NULL, reported_vs_estimated TEXT NOT NULL, gross_vs_net TEXT NOT NULL, comparable_series_id TEXT, record_json TEXT NOT NULL);
CREATE TABLE funding_rounds (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), claim_id TEXT NOT NULL REFERENCES claims(id), event_key TEXT NOT NULL, round_name TEXT NOT NULL, segment_scope TEXT NOT NULL, qualifier TEXT NOT NULL, status TEXT NOT NULL, announced_on TEXT NOT NULL, closed_on TEXT, amount REAL CHECK(amount >= 0), currency TEXT, capital_type TEXT NOT NULL, amount_basis TEXT NOT NULL, include_in_total INTEGER NOT NULL CHECK(include_in_total IN (0,1)), inclusion_reason TEXT NOT NULL, parent_round_id TEXT REFERENCES funding_rounds(id), record_json TEXT NOT NULL, UNIQUE(company_id,event_key));
CREATE TABLE company_relationships (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), related_company_id TEXT REFERENCES companies(id), related_entity_name TEXT NOT NULL, relationship TEXT NOT NULL, claim_id TEXT NOT NULL REFERENCES claims(id), as_of TEXT NOT NULL, record_json TEXT NOT NULL);
CREATE TABLE people (id TEXT PRIMARY KEY, name TEXT NOT NULL, record_json TEXT NOT NULL);
CREATE TABLE company_people (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), person_id TEXT NOT NULL REFERENCES people(id), role TEXT NOT NULL, claim_id TEXT NOT NULL REFERENCES claims(id), record_json TEXT NOT NULL);
CREATE TABLE investors (id TEXT PRIMARY KEY, name TEXT NOT NULL, record_json TEXT NOT NULL);
CREATE TABLE round_investors (id TEXT PRIMARY KEY, round_id TEXT NOT NULL REFERENCES funding_rounds(id), investor_id TEXT NOT NULL REFERENCES investors(id), role TEXT NOT NULL, claim_id TEXT NOT NULL REFERENCES claims(id), record_json TEXT NOT NULL);
CREATE TABLE customer_evidence (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), organization TEXT NOT NULL, segment_scope TEXT NOT NULL, paid_status TEXT NOT NULL, relationship TEXT NOT NULL, claim_id TEXT NOT NULL REFERENCES claims(id), disclosure TEXT NOT NULL, record_json TEXT NOT NULL);
CREATE TABLE assessments (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), segment_scope TEXT NOT NULL, rubric_version TEXT NOT NULL, as_of TEXT NOT NULL, reviewer TEXT NOT NULL, stage_limitations TEXT NOT NULL, material_conflict INTEGER NOT NULL, stale_source_caveat TEXT, gates TEXT NOT NULL, record_json TEXT NOT NULL, UNIQUE(company_id,segment_scope));
CREATE TABLE classifications (company_id TEXT REFERENCES companies(id), segment_scope TEXT NOT NULL, stage TEXT NOT NULL, confidence TEXT NOT NULL, rubric_version TEXT NOT NULL, PRIMARY KEY(company_id,segment_scope));
CREATE INDEX metrics_company_kind_date ON metrics(company_id,kind,as_of DESC);
CREATE INDEX claims_company ON claims(company_id);
CREATE INDEX evidence_source ON claim_sources(source_id);
CREATE VIEW distinct_new_capital AS SELECT company_id,currency,capital_type,COUNT(*) AS counted_rounds,SUM(amount) AS observed_round_sum FROM funding_rounds WHERE include_in_total=1 AND amount_basis='new_capital' GROUP BY company_id,currency,capital_type;
CREATE VIEW company_evidence AS SELECT c.id,c.name,COUNT(DISTINCT cl.id) AS claim_count,COUNT(DISTINCT cs.source_id) AS source_count FROM companies c LEFT JOIN claims cl ON cl.company_id=c.id LEFT JOIN claim_sources cs ON cs.claim_id=cl.id GROUP BY c.id;

CREATE TABLE products (id TEXT PRIMARY KEY, company_id TEXT REFERENCES companies(id), claim_id TEXT REFERENCES claims(id), name TEXT NOT NULL, segment_scope TEXT NOT NULL, delivery_model TEXT NOT NULL, work_performed TEXT NOT NULL, record_json TEXT NOT NULL);

CREATE TABLE company_investors (id TEXT PRIMARY KEY, company_id TEXT REFERENCES companies(id), investor_id TEXT REFERENCES investors(id), claim_id TEXT REFERENCES claims(id), allocation TEXT NOT NULL, record_json TEXT NOT NULL);

CREATE VIEW disclosed_primary_capital AS SELECT company_id,currency,COUNT(*) AS disclosed_events,SUM(amount) AS disclosed_primary_sum FROM funding_rounds WHERE json_extract(record_json,'$.include_in_disclosed_primary_sum')=1 GROUP BY company_id,currency;
